// Generated dc/ac quantizer lookup tables (AV1 spec). Do not edit by hand.
import 'package:rohd/rohd.dart';
import 'package:rohd_bridge/rohd_bridge.dart';

/// Harbor AV1 qindex -> dc/ac dequant lookup (8/10/12-bit).
///
/// Maps a base qindex plus a signed delta to the dc and ac quantizer values via
/// the libaom `dc_qlookup_QTX` / `ac_qlookup_QTX` tables for the build-time
/// [bitDepth]. Each output is `lookup[clamp(qindex + delta, 0, 255)]`. The frame
/// header supplies the qindex (`base_q_idx`) and per-plane dc/ac deltas, the
/// decode path needs the resolved dc/ac values for [HarborDequant]. Combinational.
class HarborQuantLookup extends BridgeModule {
  /// Sample bit depth (8, 10, or 12).
  final int bitDepth;

  HarborQuantLookup({this.bitDepth = 8, String? name})
    : assert(bitDepth == 8 || bitDepth == 10 || bitDepth == 12, 'bit depth'),
      super('HarborQuantLookup', name: name ?? 'quant_lookup_$bitDepth') {
    createPort('qindex', PortDirection.input, width: 8);
    createPort('delta_dc', PortDirection.input, width: 8); // signed
    createPort('delta_ac', PortDirection.input, width: 8); // signed
    addOutput('dc_q', width: 16);
    addOutput('ac_q', width: 16);

    final qindex = input('qindex');
    final deltaDc = input('delta_dc');
    final deltaAc = input('delta_ac');

    // clamp(qindex + delta, 0, 255) with a signed delta.
    Logic clampQ(Logic delta) {
      final sum =
          (qindex.zeroExtend(11) + [delta[7].replicate(3), delta].concat())
              .getRange(0, 11);
      final neg = sum[10];
      final tooBig = ~neg & ~sum.getRange(8, 11).eq(Const(0, width: 3));
      return mux(
        neg,
        Const(0, width: 8),
        mux(tooBig, Const(255, width: 8), sum.getRange(0, 8)),
      );
    }

    final dcRoms = {
      8: '',
      10: '',
      12: '',
    };
    final acRoms = {
      8: '',
      10: '',
      12: '',
    };
    final romDc = Const(BigInt.parse(dcRoms[bitDepth]!), width: 256 * 16);
    final romAc = Const(BigInt.parse(acRoms[bitDepth]!), width: 256 * 16);
    Logic romGet(Logic rom, Logic idx) {
      final shift = [idx, Const(0, width: 4)].concat(); // idx * 16
      return (rom >>> shift.zeroExtend(256 * 16)).getRange(0, 16);
    }

    output('dc_q') <= romGet(romDc, clampQ(deltaDc));
    output('ac_q') <= romGet(romAc, clampQ(deltaAc));
  }
}
